const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
// SEC-3: shared-token check — chi kiem tra khi ANSER_WEBHOOK_TOKEN da duoc cau hinh
const expectedToken = $env.ANSER_WEBHOOK_TOKEN || '';
if (expectedToken && ((raw.headers || {})['x-anser-token'] || '') !== expectedToken) {
  return [{ json: { valid: false, error: 'Unauthorized: thieu hoac sai header x-anser-token' } }];
}
if (!body.name) {
  return [{ json: { valid: false, error: 'Thiếu tên khách hàng (name)' } }];
}
return [{ json: {
  valid: true,
  name:    String(body.name),
  email:   body.email || null,
  phone:   body.phone || null,
  address: body.address || null,
  request_body: JSON.stringify({ name: body.name, email: body.email || null, phone: body.phone || null, address: body.address || null })
} }];

const db = $input.first().json;
const orig = $('Validate thông tin').first().json;
// PII masking (NT6 PDF1): che SĐT/email khi hiển thị ra kênh thông báo
const maskPhone = p => p ? String(p).replace(/.(?=.{3})/g, 'X') : 'Chưa có';
const maskEmail = e => { if (!e) return 'Chưa có'; const [u,d] = String(e).split('@'); return (u ? u[0] + '***' : '***') + (d ? '@' + d : ''); };
const body = {
  embeds: [{
    title: '👋 Khách hàng mới!',
    color: 3447003,
    fields: [
      { name: 'Tên', value: orig.name, inline: true },
      { name: 'Mã KH', value: db.code || '—', inline: true },
      { name: 'SĐT', value: maskPhone(orig.phone), inline: true },
      { name: 'Email', value: maskEmail(orig.email), inline: true },
      { name: 'Địa chỉ', value: orig.address || 'Chưa có', inline: false }
    ],
    footer: { text: 'ANSER CRM • PII masked' },
    timestamp: new Date().toISOString()
  }]
};
const resp = { status: 'ok', id: db.id, code: db.code, name: orig.name };
return [{ json: { discord_body: JSON.stringify(body), response_201: JSON.stringify(resp) } }];
